   188	  p.deadlineMs = num("LOCAL_LLM_RECOVERY_DEADLINE_MS", p.deadlineMs);
   189	  p.firstContactDeadlineMs = num("NEXUS_FIRST_CONTACT_DEADLINE_MS", p.firstContactDeadlineMs ?? 120_000);
   190	  p.baseDelayMs = num("LOCAL_LLM_RECOVERY_BASE_DELAY_MS", p.baseDelayMs, 1);
   191	  p.maxDelayMs = Math.max(num("LOCAL_LLM_RECOVERY_MAX_DELAY_MS", p.maxDelayMs, 1), p.baseDelayMs);
   192	  p.minDelayMs = Math.min(num("LOCAL_LLM_RECOVERY_MIN_DELAY_MS", p.minDelayMs, 1), p.maxDelayMs);
   193	  p.probeTimeoutMs = num("LOCAL_LLM_RECOVERY_PROBE_TIMEOUT_MS", p.probeTimeoutMs, 1);
