   737	/**
   738	 * Continuation budgets: flags, then NEXUS_MAX_TOTAL_STEPS / NEXUS_MAX_TURN_MINUTES / NEXUS_STAGNATION_STEPS, then
   739	 * defaults. There is no default step or time ceiling: progressing work continues until it completes, is cancelled,
   740	 * stagnates or fails. A step or time limit exists only when the operator sets one. `--no-continuation` (or
   741	 * NEXUS_CONTINUATION=0) is the operator's explicit choice of the single-segment turn that ends at --max-steps.
   742	 */
   743	export function continuationBudget(options: any): ContinuationBudget | undefined {
   744	  if (options.continuation === false || effectiveSetting("NEXUS_CONTINUATION") === "0") return undefined;
   745	  const positive = (flag: unknown, env: string | undefined, fallback: number): number => {
   746	    for (const raw of [flag, env]) {
   747	      if (raw === undefined || raw === null || raw === "") continue;
   748	      const value = Number(raw);
   749	      if (!Number.isFinite(value) || value <= 0) throw new Error(`Invalid continuation budget '${String(raw)}': expected a positive number.`);
   750	      return value;
   751	    }
   752	    return fallback;
   753	  };
   754	  const steps = positive(options.maxTotalSteps, effectiveSetting("NEXUS_MAX_TOTAL_STEPS"), DEFAULT_CONTINUATION.maxTotalSteps);
   755	  return {
   756	    ...DEFAULT_CONTINUATION,
   757	    maxTotalSteps: Number.isFinite(steps) ? Math.floor(steps) : steps,
   758	    maxTurnMinutes: positive(options.maxTurnMinutes, effectiveSetting("NEXUS_MAX_TURN_MINUTES"), DEFAULT_CONTINUATION.maxTurnMinutes),
   759	    stagnationSteps: Math.floor(positive(options.stagnationSteps, effectiveSetting("NEXUS_STAGNATION_STEPS"), DEFAULT_CONTINUATION.stagnationSteps)),
   760	    verifierConvergenceAttempts: Math.floor(positive(undefined, effectiveSetting("NEXUS_VERIFIER_CONVERGENCE_ATTEMPTS"), DEFAULT_CONVERGENCE_ATTEMPTS)),
   761	  };
   762	}
