   421	export function assertTurnResultInvariants(t: TurnResult): TurnResult {
   422	  if (t.outcome === "VERIFIED") {
   423	    if (t.execution !== "COMPLETED") throw new TurnResultInvariantError("VERIFIED requires execution COMPLETED");
