   425	    if (!v || v.status !== "PASSED" || !v.command || v.exitSuccess !== true) {
   426	      throw new TurnResultInvariantError("VERIFIED requires passing verifier evidence");
   427	    }
   428	    if (t.unverifiedChangesPending) throw new TurnResultInvariantError("VERIFIED conflicts with pending unverified changes");
   429	  }
   430	  if (t.outcome === "REGRESSION_FREE") {
   431	    if (t.execution !== "COMPLETED") throw new TurnResultInvariantError("REGRESSION_FREE requires execution COMPLETED");
   432	    const v = t.verification;
   433	    if (!v || v.status !== "PASSED" || !v.command || v.exitSuccess !== true) {
   434	      throw new TurnResultInvariantError("REGRESSION_FREE requires passing verifier evidence");
   435	    }
   436	  }
   437	  if (t.outcome === "NOT_REQUIRED" && (t.execution !== "COMPLETED" || t.unverifiedChangesPending)) {
   438	    throw new TurnResultInvariantError("NOT_REQUIRED requires a completed turn with no pending changes");
   439	  }
   440	  if (t.execution === "INTERRUPTED" && !t.interruption) throw new TurnResultInvariantError("INTERRUPTED requires an interruption record");
   441	  if (t.execution === "INTERRUPTED" && t.outcome !== "NOT_ESTABLISHED") {
   442	    throw new TurnResultInvariantError("INTERRUPTED must not claim an engineering outcome");
   443	  }
   444	  if (t.execution === "BLOCKED" && t.outcome !== "NOT_ESTABLISHED") {
   445	    throw new TurnResultInvariantError("BLOCKED must not claim an engineering outcome");
   446	  }
   447	  if (t.reason === "VERIFIER_NOT_CONVERGING" && (t.execution !== "BLOCKED" || t.outcome !== "NOT_ESTABLISHED" || !t.convergence)) {
   448	    throw new TurnResultInvariantError("VERIFIER_NOT_CONVERGING requires a BLOCKED, NOT_ESTABLISHED turn carrying its attempt history");
