import { createHash } from "node:crypto";

export const CAPABILITY_DOMAINS = [
  "code_comprehension",
  "scoped_implementation",
  "multi_file_refactoring",
  "dependency_analysis",
  "tool_selection",
  "context_compaction",
  "session_persistence",
  "retry_backoff",
  "rate_limit_recovery",
  "model_escalation",
  "specialist_delegation",
  "independent_review",
  "authorization_enforcement",
  "workspace_isolation",
  "semantic_integrity",
] as const;
export type CapabilityDomain = (typeof CAPABILITY_DOMAINS)[number];

export interface DeterministicAssertion {
  id: string;
  description: string;
  command?: string;
  expectedExitCode?: number;
  expectedStdoutPattern?: string;
}

export interface EvaluationDefinition {
  id: string;
  version: string;
  domain: CapabilityDomain;
  objective: string;
  fixturePath: string;
  initialCommit?: string;
  expectedOutputs: string[];
  authorizedTools: string[];
  executionBudget: {
    maxSteps: number;
    timeoutSeconds: number;
    maxTokens?: number;
  };
  deterministicAssertions: DeterministicAssertion[];
  independentValidationCriteria: string[];
  knownNondeterminism?: string[];
}

export interface ModelMetadata {
  name: string;
  digest?: string;
  quantization?: string;
  parameters: {
    temperature: number;
    topP?: number;
    maxTokens?: number;
    seed?: number;
  };
}

export interface EnvironmentMetadata {
  os: string;
  kernel: string;
  nodeVersion: string;
  bubblewrapVersion?: string;
}

export interface HardwareMetadata {
  cpuModel: string;
  gpuModel?: string;
  totalMemoryBytes: number;
}

export type RunStatus =
  | "RUNNING"
  | "COMPLETED"
  | "INTERRUPTED"
  | "FAILED"
  | "CANCELLED"
  | "INCONCLUSIVE"
  | "NOT_EXECUTED"
  | "INFRASTRUCTURE_FAILURE"
  | "EVALUATOR_DEFECT";

export interface RunManifest {
  runId: string;
  evaluationId: string;
  evaluationVersion: string;
  sourceCommit: string;
  dirtyWorktree: boolean;
  uncommittedDiffHash?: string;
  model: ModelMetadata;
  routingConfig: {
    gatewayUrl: string;
    taskClass?: string;
    specialistRouting: boolean;
  };
  agentProfileVersion: string;
  harnessVersion: string;
  /** Content hash of the evaluation fixture (`hashFixture`); absent means the fixture identity was not recorded. */
  fixtureSha256?: string;
  toolchainVersions: Record<string, string>;
  environment: EnvironmentMetadata;
  hardware: HardwareMetadata;
  startedAt: string;
  completedAt?: string;
  durationMs?: number;
  status: RunStatus;
  terminationReason?: string;
  mandatoryComparabilityKeys: string[];
}

export type ComparativeOutcome =
  | "PASS"
  | "FAIL"
  | "REGRESSION_CANDIDATE"
  | "CONFIRMED_REGRESSION"
  | "IMPROVEMENT_CANDIDATE"
  | "FLAKY"
  | "INFRASTRUCTURE_FAILURE"
  | "EVALUATOR_DEFECT"
  | "INCONCLUSIVE"
  | "NOT_EXECUTED"
  | "CANCELLED"
  | "INCOMPARABLE";

export interface BaselineIdentity {
  manifestSha256: string;
  model: { name: string; digest?: string; quantization?: string };
  sampling: ModelMetadata["parameters"];
  configurationSha256: string;
  evaluatorVersion: string;
  fixtureSha256?: string;
  toolchainVersions: Record<string, string>;
}

/**
 * IDENTITY_BOUND: the baseline identity was recorded, verified against the baseline manifest the caller supplied, and
 * matches the current run. UNBOUND: anything less (the existing "non-certifying" case).
 * This is a local, unsigned identity binding; not external qualification; an attacker who edits manifest, hash and
 * identity together passes.
 */
export type IdentityBindingStatus = "IDENTITY_BOUND" | "UNBOUND";

export interface BaselineSpecification {
  baselineId: string;
  evaluationId: string;
  evaluationVersion: string;
  sourceCommit: string;
  modelName: string;
  modelQuantization?: string;
  selectionRationale: string;
  manifestSha256: string;
  establishedAt: string;
  assertions?: Record<string, boolean>;
  identity?: BaselineIdentity;
}

export interface BaselineComparisonResult {
  baselineId: string;
  currentRunId: string;
  isEligibleForComparison: boolean;
  incomparabilityReasons?: string[];
  outcome: ComparativeOutcome;
  divergences: Array<{
    assertionId: string;
    baselineStatus: "PASS" | "FAIL";
    currentStatus: "PASS" | "FAIL";
    details: string;
  }>;
  confidence: number;
  explanation: string;
  /**
   * True only for a comparison against a VerifiedBaseline (evidence loaded through the integrity check) whose identity
   * is IDENTITY_BOUND. Everything else is non-certifying. Local and unsigned, like the identity binding itself.
   */
  certifying?: boolean;
  identityBinding?: {
    status: IdentityBindingStatus;
    reasons: string[];
    /** Every identity field that differs between baseline and candidate (or is not recorded), e.g. "model.digest". */
    mismatchedFields?: string[];
    baselineIdentity?: BaselineIdentity;
    currentIdentity: BaselineIdentity;
  };
}

export type EpistemologicalType =
  | "OBSERVATION"
  | "INFERENCE"
  | "HYPOTHESIS"
  | "CONFIRMED_FINDING"
  | "UNRESOLVED_UNCERTAINTY";

export interface InvestigationFinding {
  id: string;
  type: EpistemologicalType;
  description: string;
  evidenceReferences: string[];
  timestamp: string;
}

export interface RemediationProposal {
  id: string;
  targetIssue: string;
  authorAgent: string;
  reproductionSteps: string[];
  proposedDiff: string;
  testRecommendations: string[];
  approvalStatus: "PENDING_REVIEW" | "APPROVED" | "REJECTED";
  reviewerAgent?: string;
  reviewDecisionRationale?: string;
  createdAt: string;
}

export interface CeriOperationalReport {
  identityBinding?: { bound: number; unbound: number; reasons: string[] };
  reportId: string;
  generatedAt: string;
  evaluationCoverage: {
    totalEvaluations: number;
    /** Distinct evaluation ids with at least one run; coverage is computed from this, not from the run count. */
    executedEvaluations: number;
