      runner: RUNNER,
      configPath: runnerConfigPath,
      dataset: normalized.dataset,
      outputDir: normalized.outputDir,
      runs: normalized.runs,
      split: normalized.split,
      cwd: options.cwd ? path.resolve(options.cwd) : process.cwd(),
