    return {
      outputDir: normalized.outputDir,
      resultsFile,
      manifestFile: path.join(normalized.outputDir, "manifest.json"),
      scoreFile,
      score,
    };
  } finally {
    fs.rmSync(privateDir, { recursive: true, force: true });
  }
}
