  assert.equal(JSON.stringify(first).includes("secret-value"), false);
  assert.throws(() => createRequestContextManifest({ messages: [{ content: "x".repeat(32 * 1024 * 1024) }], tools: [], parameters: {} }), /exceeds/);
});

